_TERMS = ('Python', 'FastAPI', 'Flask', 'Django', 'JavaScript', 'TypeScript', 'Java', 'C++', 'C#',
          'SQL', 'PostgreSQL', 'MySQL', 'Redis', 'SQLite', 'Docker', 'Kubernetes', 'K8s', 'Linux',
